def countOfPeaks(nums, queries):
    n = len(nums)
    size = 1
    while size < n:
        size *= 2

    # A node is (first_peak, last_peak, B); (-1, -1, 0) means "no peaks"
    EMPTY = (-1, -1, 0)

    def merge(x, y):
        if x[0] == -1:
            return y
        if y[0] == -1:
            return x
        # B accumulates (p_t - p_{t-1}) * p_t over consecutive peaks
        return (x[0], y[1], x[2] + y[2] + (y[0] - x[1]) * y[0])

    # Is index k a strict local peak?
    def is_peak(k):
        return 0 < k < n - 1 and nums[k] > nums[k - 1] and nums[k] > nums[k + 1]

    # Build an iterative segment tree over positions
    tree = [EMPTY] * (2 * size)
    for k in range(n):
        if is_peak(k):
            tree[size + k] = (k, k, 0)
    for i in range(size - 1, 0, -1):
        tree[i] = merge(tree[2 * i], tree[2 * i + 1])

    # Recompute the leaf for position k and update its ancestors
    def refresh(k):
        if 0 <= k < n:
            i = size + k
            tree[i] = (k, k, 0) if is_peak(k) else EMPTY
            i //= 2
            while i:
                tree[i] = merge(tree[2 * i], tree[2 * i + 1])
                i //= 2

    # Ordered range query over positions [lo, hi]
    def query(lo, hi):
        left, right = EMPTY, EMPTY
        lo += size
        hi += size + 1
        while lo < hi:
            if lo & 1:
                left = merge(left, tree[lo])
                lo += 1
            if hi & 1:
                hi -= 1
                right = merge(tree[hi], right)
            lo //= 2
            hi //= 2
        return merge(left, right)

    answer = []
    for t, x, y in queries:
        if t == 1:
            l, r = x, y
            # Only peak positions strictly inside (l, r) can count
            if r - l < 2:
                answer.append(0)
                continue
            first, last, B = query(l + 1, r - 1)
            if first == -1:
                answer.append(0)
            else:
                # Left ends grouped by their next peak position
                answer.append((first - l) * (r - first) + r * (last - first) - B)
        else:
            # Point update: only positions x-1, x, x+1 can change peak status
            nums[x] = y
            refresh(x - 1)
            refresh(x)
            refresh(x + 1)
    return answer
